<?php ob_start(); ?><section class="section"><div class="section-head"><div><p class="eyebrow">Planning</p><h1>Reservations</h1></div><a class="button" href="/reservations/create">Reserver une salle</a></div><div class="table-wrap"><table><thead><tr><th>Salle</th><th>Responsable</th><th>Debut</th><th>Fin</th><th>Statut</th><th></th></tr></thead><tbody><?php foreach ($reservations as $reservation): ?><tr><td><?= htmlspecialchars($reservation->salle->nom) ?></td><td><?= htmlspecialchars($reservation->responsable) ?></td><td><?= $reservation->date_debut->format('d/m/Y H:i') ?></td><td><?= $reservation->date_fin->format('d/m/Y H:i') ?></td><td><span class="status <?= $reservation->statut === 'confirmee' ? 'on' : 'off' ?>"><?= htmlspecialchars($reservation->statut) ?></span></td><td><a href="/reservations/<?= $reservation->id ?>">Voir</a></td></tr><?php endforeach; ?></tbody></table></div></section><?php $content = ob_get_clean(); require dirname(__DIR__) . '/layout/base.php';